arguments.command:
cd /app/dclm && python3 - <<'PY'
import os,re
subs_literal={
 "D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF":"<your-aws-secret-access-key>",
 "<redacted-aws-key>":"<your-aws-access-key-id>",
 "<redacted-github-token>":"<your-github-token>",
}
subs_re=[
 (re.compile(r"AKIA[0-9A-Z]{16}"),"<your-aws-access-key-id>"),
 (re.compile(r"ghp_[A-Za-z0-9]{30,}"),"<your-github-token>"),
 (re.compile(r"github_pat_[A-Za-z0-9_]{30,}"),"<your-github-token>"),
 (re.compile(r"hf_[A-Za-z0-9]{25,}"),"<your-huggingface-token>"),
]
changed=[]
for root,dirs,files in os.walk("."):
    if "/.git" in root or root.startswith("./.git"): 
        dirs[:]=[d for d in dirs if d!=".git"]
    dirs[:]=[d for d in dirs if d!=".git" and d!=".lemoncrow"]
    for fn in files:
        p=os.path.join(root,fn)
        try:
            with open(p,encoding="utf-8") as f: s=f.read()
        except (UnicodeDecodeError,IsADirectoryError,PermissionError):
            continue
        o=s
        for a,b in subs_literal.items(): s=s.replace(a,b)
        for rx,b in subs_re: s=rx.sub(b,s)
        if s!=o:
            with open(p,"w",encoding="utf-8") as f: f.write(s)
            changed.append(p)
print("CHANGED:",changed)
PY
